import{_ as t,a as s,c as r,ac as a}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"Kubernetes 知识体系","description":"Kubernetes 学习顺序与生产操作入口","frontmatter":{"title":"Kubernetes 知识体系","description":"Kubernetes v1.36 中文知识库，涵盖架构、对象、工作负载、网络、存储、安全、运维和排障","sources":[{"repository":"TeamDocs","file":"docs/engineering/kubernetes/index.md"}],"showdocs":{"topics":[{"id":"kubernetes","title":"Kubernetes","link":"/topics/kubernetes/"}],"kind":"故障排查","scope":"general","audience":"general","group":"容器与运维","summary":"Kubernetes 学习顺序与生产操作入口","status":"active","related":[{"title":"Helm 基础与进阶","link":"/systems/kubernetes/base/basic/helm","kind":"知识专题","scope":"general","audience":"general"},{"title":"kubectl 基础命令","link":"/systems/kubernetes/base/basic/04-kubectl-basics","kind":"知识专题","scope":"general","audience":"general"},{"title":"Kubernetes 操作与命令","link":"/systems/kubernetes/plus/ecosystem/kubernetes-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Kubernetes 存储","link":"/systems/kubernetes/plus/subjects/08-storage","kind":"知识专题","scope":"general","audience":"general"},{"title":"Kubernetes 调度","link":"/systems/kubernetes/plus/subjects/10-scheduling","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":false},"prev":false,"next":false},"headers":[],"relativePath":"systems/kubernetes/overview.md","filePath":"systems/kubernetes/overview.md"}'),n={name:"systems/kubernetes/overview.md"};function i(d,e,l,o,c,u){return s(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="kubernetes-知识体系" tabindex="-1">Kubernetes 知识体系 <a class="header-anchor" href="#kubernetes-知识体系" aria-label="Permalink to &quot;Kubernetes 知识体系&quot;">​</a></h1><p>本知识库面向需要开发、发布和运维 Kubernetes 工作负载的工程师。内容以原生 Kubernetes 为主，命令示例默认使用 Bash、<code>kubectl</code> 和命名空间 <code>demo</code>。</p><div class="tip custom-block"><p class="custom-block-title">版本基线</p><p>截至 <strong>2026-08-12</strong>，Kubernetes 最新稳定版是 <strong>v1.36.3</strong>，上游维护的三个次要版本分支是 <strong>1.36、1.35、1.34</strong>。版本信息以 <a href="https://dl.k8s.io/release/stable.txt" target="_blank" rel="noopener noreferrer"><code>stable.txt</code></a>、<a href="https://github.com/kubernetes/kubernetes/releases/tag/v1.36.3" target="_blank" rel="noopener noreferrer">GitHub v1.36.3 Release</a> 和<a href="https://kubernetes.io/releases/version-skew-policy/" target="_blank" rel="noopener noreferrer">版本偏差策略</a>为依据。预发布的 v1.37.0-rc.0 不是生产稳定版。详见<a href="/systems/kubernetes/plus/subjects/01-version-and-setup">版本与环境</a>。</p></div><h2 id="阅读地图" tabindex="-1">阅读地图 <a class="header-anchor" href="#阅读地图" aria-label="Permalink to &quot;阅读地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>章节</th><th>目标</th></tr></thead><tbody><tr><td>入门</td><td><a href="/systems/kubernetes/plus/subjects/01-version-and-setup">版本与环境</a></td><td>选版本、安装客户端、安全连接集群</td></tr><tr><td>原理</td><td><a href="/systems/kubernetes/plus/subjects/02-architecture-and-api">架构与 API</a></td><td>理解控制面、节点、声明式控制循环</td></tr><tr><td>原理</td><td><a href="/systems/kubernetes/plus/subjects/03-objects-and-manifests">对象与清单</a></td><td>正确编写 YAML、标签、选择器和所有权关系</td></tr><tr><td>操作</td><td><a href="/systems/kubernetes/base/basic/04-kubectl-basics">kubectl 基础</a></td><td>查询、创建、更新、删除和查看日志</td></tr><tr><td>操作</td><td><a href="/systems/kubernetes/plus/practice/05-kubectl-advanced">kubectl 进阶</a></td><td>JSONPath、调试、代理、补丁和服务端应用</td></tr><tr><td>应用</td><td><a href="/systems/kubernetes/plus/subjects/06-workloads">工作负载</a></td><td>选择 Pod、Deployment、StatefulSet、DaemonSet、Job</td></tr><tr><td>应用</td><td><a href="/systems/kubernetes/plus/subjects/07-configuration">配置管理</a></td><td>管理 ConfigMap、Secret、ServiceAccount 和环境变量</td></tr><tr><td>基础设施</td><td><a href="/systems/kubernetes/plus/subjects/08-storage">存储</a></td><td>理解 Volume、PV、PVC、StorageClass 和快照</td></tr><tr><td>基础设施</td><td><a href="/systems/kubernetes/plus/subjects/09-networking">网络</a></td><td>理解 Pod 网络、Service、DNS、Ingress、Gateway 和策略</td></tr><tr><td>基础设施</td><td><a href="/systems/kubernetes/plus/subjects/10-scheduling">调度</a></td><td>控制节点选择、亲和性、污点、拓扑分布和优先级</td></tr><tr><td>可靠性</td><td><a href="/systems/kubernetes/plus/subjects/11-resources-and-health">资源与健康检查</a></td><td>配置 requests/limits、QoS、探针和生命周期</td></tr><tr><td>可靠性</td><td><a href="/systems/kubernetes/plus/subjects/12-autoscaling">扩缩容</a></td><td>使用 HPA、VPA、节点扩容并避免控制器冲突</td></tr><tr><td>安全</td><td><a href="/systems/kubernetes/plus/subjects/13-security-rbac">RBAC 与安全</a></td><td>最小权限、Pod Security、Secret 与供应链防护</td></tr><tr><td>运维</td><td><a href="/systems/kubernetes/plus/subjects/14-observability">可观测性</a></td><td>统一指标、日志、事件、审计和告警</td></tr><tr><td>运维</td><td><a href="/systems/kubernetes/plus/troubleshooting/15-troubleshooting">排障手册</a></td><td>从症状沿 Pod、网络、存储、节点逐层定位</td></tr><tr><td>运维</td><td><a href="/systems/kubernetes/plus/subjects/16-upgrade-maintenance">升级与维护</a></td><td>规划版本、备份、滚动升级、节点维护与回退</td></tr><tr><td>生产</td><td><a href="/systems/kubernetes/plus/practice/17-production-practices">生产实践</a></td><td>落地高可用、变更治理、容量、安全和灾备基线</td></tr><tr><td>速查</td><td><a href="/systems/kubernetes/plus/ecosystem/18-command-reference">命令速查</a></td><td>按场景快速找到常用与高风险命令</td></tr></tbody></table><h2 id="核心心智模型" tabindex="-1">核心心智模型 <a class="header-anchor" href="#核心心智模型" aria-label="Permalink to &quot;核心心智模型&quot;">​</a></h2><p>Kubernetes 不是“运行容器的命令行工具”，而是一个持续协调期望状态与实际状态的分布式控制系统：</p><ol><li>用户向 API Server 提交对象的期望状态。</li><li>API Server 完成认证、鉴权、准入和持久化。</li><li>控制器观察对象并创建或更新下游对象。</li><li>Scheduler 为未绑定的 Pod 选择节点。</li><li>节点上的 kubelet 通过容器运行时、网络和存储插件实现 Pod。</li><li>状态变化重新写回 API，控制循环持续收敛。</li></ol><p>因此，生产操作应优先修改声明式配置并交给控制器收敛；直接改某个 Pod 通常只会得到暂时效果。</p><h2 id="示例约定" tabindex="-1">示例约定 <a class="header-anchor" href="#示例约定" aria-label="Permalink to &quot;示例约定&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 明确当前上下文和命名空间，避免误操作</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> current-context</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-context</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --current</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --namespace=demo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只读命令可以先执行；写操作先做服务端 dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server-side</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run=server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.yaml</span></span></code></pre></div><ul><li><code>&lt;pod&gt;</code>、<code>&lt;node&gt;</code>、<code>&lt;namespace&gt;</code> 是占位符，执行前必须替换。</li><li>命令未写 <code>-n</code> 时，使用当前上下文的默认命名空间。</li><li>YAML 中镜像均固定版本；生产环境建议进一步固定镜像 digest。</li><li><code>kubectl run</code>、<code>kubectl create</code> 适合调试或生成草稿，长期配置应进入 Git。</li><li>文档中的云负载均衡器、CSI、CNI、Gateway API 等能力取决于集群发行版和已安装插件。</li></ul><h2 id="操作安全等级" tabindex="-1">操作安全等级 <a class="header-anchor" href="#操作安全等级" aria-label="Permalink to &quot;操作安全等级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>典型操作</th><th>要求</th></tr></thead><tbody><tr><td>只读</td><td><code>get</code>、<code>describe</code>、<code>logs</code>、<code>top</code>、<code>auth can-i</code></td><td>核对上下文和命名空间</td></tr><tr><td>可回滚写入</td><td><code>apply</code>、<code>scale</code>、<code>rollout restart</code></td><td>先 <code>diff</code>/dry-run，观察 rollout</td></tr><tr><td>高风险</td><td><code>delete</code>、<code>drain</code>、<code>cordon</code>、强制替换</td><td>明确对象、影响窗口和恢复步骤</td></tr><tr><td>灾难级</td><td>删除命名空间/PV、<code>--force --grace-period=0</code>、etcd 恢复</td><td>变更审批、备份、双人复核、演练</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">不要复制即执行</p><p>执行任何写命令前，至少运行 <code>kubectl config current-context</code>、<code>kubectl cluster-info</code> 和目标对象的只读查询。生产集群不要依赖 shell 历史中的默认命名空间。</p></div><h2 id="官方资料" tabindex="-1">官方资料 <a class="header-anchor" href="#官方资料" aria-label="Permalink to &quot;官方资料&quot;">​</a></h2><ul><li><a href="https://kubernetes.io/docs/" target="_blank" rel="noopener noreferrer">Kubernetes 官方文档</a></li><li><a href="https://kubernetes.io/docs/reference/generated/kubernetes-api/v1.36/" target="_blank" rel="noopener noreferrer">Kubernetes API Reference v1.36</a></li><li><a href="https://kubernetes.io/docs/reference/kubectl/" target="_blank" rel="noopener noreferrer">kubectl 命令参考</a></li><li><a href="https://kubernetes.io/releases/" target="_blank" rel="noopener noreferrer">Kubernetes Releases</a></li><li><a href="https://github.com/kubernetes/kubernetes/releases" target="_blank" rel="noopener noreferrer">Kubernetes GitHub Releases</a></li><li><a href="https://kubernetes.io/docs/reference/issues-security/security/" target="_blank" rel="noopener noreferrer">Kubernetes 安全公告</a></li></ul>`,17)])])}const k=t(n,[["render",i]]);export{p as __pageData,k as default};
